INHERITED_STYLES_SITE, true );
$theme = get_stylesheet();

// Start clean: only the shared page, no sample post or pages.
foreach ( get_posts( array( 'post_type' => array( 'post', 'page' ), 'post_status' => 'any', 'numberposts' => -1 ) ) as $p ) {
	wp_delete_post( $p->ID, true );
}
update_option( 'wp_page_for_privacy_policy', 0 );
update_option( 'blogname', $site['blogname'] );
update_option( 'blogdescription', $site['description'] );

// Images, with the same IDs as in Studio when possible.
$uploads = wp_upload_dir();
$ids     = array();
foreach ( $site['attachments'] as $a ) {
	$path = $uploads['basedir'] . '/' . $a['relative'];
	wp_mkdir_p( dirname( $path ) );
	file_put_contents( $path, base64_decode( $a['data'] ) );
	$id = wp_insert_attachment(
		array(
			'import_id'      => $a['id'],
			'post_title'     => $a['title'],
			'post_mime_type' => $a['mime'],
			'post_status'    => 'inherit',
			'guid'           => $uploads['baseurl'] . '/' . $a['relative'],
		),
		$path
	);
	wp_update_attachment_metadata( $id, wp_generate_attachment_metadata( $id, $path ) );
	update_post_meta( $id, '_wp_attachment_image_alt', $a['alt'] );
	$ids[ $a['id'] ] = $id;
}

// Studio URLs and IDs → this site.
$fix = function ( $content ) use ( $site, $ids ) {
	$content = str_replace( $site['home'], home_url(), $content );
	foreach ( $ids as $old => $new ) {
		if ( $old !== $new ) {
			$content = preg_replace( '/\\bwp-image-' . $old . '\\b/', 'wp-image-' . $new, $content );
			$content = preg_replace( '/"id":' . $old . '\\b/', '"id":' . $new, $content );
		}
	}
	return $content;
};

// Template, template parts and navigation menus.
$insert_theme_post = function ( $type, $item ) use ( $theme, $fix ) {
	$id = wp_insert_post(
		array(
			'post_type'    => $type,
			'post_status'  => 'publish',
			'post_name'    => $item['slug'],
			'post_title'   => $item['title'],
			'post_excerpt' => $item['description'] ?? '',
			'post_content' => wp_slash( $fix( $item['content'] ) ),
		)
	);
	if ( 'wp_navigation' !== $type ) {
		wp_set_object_terms( $id, $theme, 'wp_theme' );
	}
	if ( ! empty( $item['area'] ) ) {
		wp_set_object_terms( $id, $item['area'], 'wp_template_part_area' );
	}
};
if ( $site['template'] ) {
	$insert_theme_post( 'wp_template', $site['template'] );
}
foreach ( $site['templateParts'] as $part ) {
	$insert_theme_post( 'wp_template_part', $part );
}
foreach ( $site['navigation'] as $menu ) {
	$insert_theme_post( 'wp_navigation', $menu );
}

// The page, also the site's homepage.
$page    = $site['page'];
$page_id = wp_insert_post(
	array(
		'import_id'    => $page['id'],
		'post_type'    => 'page',
		'post_status'  => 'publish',
		'post_title'   => $page['title'],
		'post_name'    => $page['slug'],
		'post_content' => wp_slash( $fix( $page['content'] ) ),
	)
);
if ( $page['template'] && 'default' !== $page['template'] ) {
	update_post_meta( $page_id, '_wp_page_template', $page['template'] );
}
if ( $page['thumb'] && isset( $ids[ $page['thumb'] ] ) ) {
	set_post_thumbnail( $page_id, $ids[ $page['thumb'] ] );
}
update_option( 'show_on_front', 'page' );
update_option( 'page_on_front', $page_id );

// Styles (global styles) as customised in Studio.
if ( $site['styles'] ) {
	wp_update_post(
		array(
			'ID'           => WP_Theme_JSON_Resolver::get_user_global_styles_post_id(),
			'post_content' => wp_slash( $site['styles'] ),
		)
	);
}

// Skip the editor's welcome guide.
update_user_meta(
	1,
	$GLOBALS['wpdb']->get_blog_prefix() . 'persisted_preferences',
	array(
		'core/edit-post' => array( 'welcomeGuide' => false ),
		'core/edit-site' => array( 'welcomeGuide' => false ),
		'_modified'      => gmdate( 'c' ),
	)
);
